    /// <summary>
    /// Sets reactions on a message; for bots only
    /// </summary>
    public Task<TdLib.TdApi.Objects.Ok> SetMessageReactionsAsync(long chatId = default, long messageId = default, ReactionType[] reactionTypes = default, bool isBig = default)
    {

           using var activity =  StartCallActivity("SetMessageReactionsAsync", typeof(SetMessageReactions).FullName ?? "SetMessageReactionsAsync");

           try
           {
             return client.SetMessageReactionsAsync(chatId, messageId, reactionTypes, isBig);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
